    @test("system_tools")
    def test_get_hub_info(self) -> None:
        result = self.client.call_tool("hub_get_info")
        assert result is not None, "hub_get_info returned None"
        assert isinstance(result, dict), f"hub_get_info returned {type(result)}"
        assert result.get("setupCurrent") is True, f"server setup is incomplete: {redact_hub_payload(result)}"
        assert result.get("setupVersion") == result.get("mcpServerVersion"), \
            f"setup did not complete for the running server version: {redact_hub_payload(result)}"
        repeated = self.client.call_tool("hub_get_info")
        assert repeated.get("setupCurrent") is True and repeated.get("setupVersion") == result["setupVersion"], \
            f"ordinary requests must retain completed setup: {redact_hub_payload(repeated)}"
        # Folded from test_hub_get_info_platform_update_and_safemode (the SAME default hub_get_info call):
        # #12/#13 -- platformUpdate + safeMode resolve from /hub2/hubData; the full alerts block stays out.
        assert "platformUpdate" in result, f"hub_get_info missing platformUpdate: {sorted(result)}"
        pu = result["platformUpdate"]
        assert "currentVersion" in pu, f"platformUpdate missing currentVersion: {pu}"
        # Firmware 2.5.2.129+ no longer reports a pending update in /hub2/hubData; available is then
        # null with a note, never a guessed false.
        assert isinstance(pu.get("available"), bool) or (pu.get("available") is None and pu.get("note")), \
            f"platformUpdate.available not resolved -- /hub2/hubData unreadable? {pu}"
        if pu["available"]:
            assert pu.get("availableVersion"), f"available=true but no availableVersion: {pu}"
        assert "safeMode" in result, f"hub_get_info missing safeMode: {sorted(result)}"
        assert "healthAlerts" not in result, "healthAlerts must be absent without includeHealthAlerts=true"
        # Readings are numbers, and the database size carries the hub's own unit (MB).
        assert isinstance(result.get("freeMemoryKB"), int), f"freeMemoryKB must be a number: {result.get('freeMemoryKB')!r}"
        assert isinstance(result.get("databaseSizeMB"), int) and "databaseSizeKB" not in result, \
            f"database size must be databaseSizeMB, a number: {result.get('databaseSizeMB')!r}"
        assert isinstance(result.get("mcpDeviceCount"), int), f"mcpDeviceCount must be a number: {result.get('mcpDeviceCount')!r}"
        # Client identity is derived from THIS request and nothing is persisted, so the record
        # handed back describes the very call that fetched it. Shape only here -- the
        # name/version capture is proved in the protocol group, which controls what the
        # client declares.
        identity = result.get("mcpClient")
        assert isinstance(identity, dict), f"hub_get_info missing mcpClient: {sorted(result)}"
        client = identity.get("client")
        assert isinstance(client, dict), f"mcpClient.client must name the caller: {identity!r}"
        assert client.get("era") == "modern", f"this suite speaks 2026-07-28: {client!r}"
        assert client.get("protocolVersion") == MODERN_PROTOCOL_VERSION, \
            f"client.protocolVersion must be the header version: {client!r}"
        assert client.get("source") in {"cloud", "local"}, f"unexpected client.source: {client!r}"
        assert isinstance(client.get("wrapper"), bool), \
            f"every identity must carry a wrapper verdict: {client!r}"
        leftovers = {"recent", "lastSeen"} & set(identity)
        assert not leftovers, f"identity is not stored between requests: {sorted(leftovers)}"
        assert "seenAt" not in client, f"identity is not stored between requests: {sorted(client)}"

    @test("system_tools")
    def test_report_issue_report_shape(self) -> None:
        # hub_report_issue is read-only -- it renders a markdown report out of MCP log history plus
        # the recorded client identity and writes nothing to the hub. It is an MRTR read tool, so a
        # still-hydrating log buffer rides a requestState continuation the client follows itself.
        def _report(args: dict) -> dict:
            res = self.client.call_tool("hub_report_issue", args)
            assert isinstance(res, dict), f"hub_report_issue returned {type(res)}"
            return res

        long_expected = (
            "The trigger should have been created and the rule should then have started listening "
            "for the switch event without any further interaction from the agent, because every "
            "required field was supplied on the very first call."
        )
        assert len(long_expected) > 150, "the wrap assertion needs prose longer than the wrap width"
        # A pasted payload that carries its own bare ``` line -- the rendered block must open on a
        # LONGER backtick run, or the paste would close the block early.
        verbatim = 'hub_set_rule({"appId": 1}) ->\n```\nHTTP 500 Internal error\n```'
        # Credentials reach the raw sections through pasted transcripts, and the report is headed
        # for a public tracker, so they are redacted in BOTH privacy modes.
        # A redaction must end at the credential: the line after one that merely ENDS in the word
        # "token", the closing quote and the URL after a header value, all have to survive.
        secret_logs = (
            "2026-01-01T00:00:00 ERROR mcp-server-hubitat: transport closed\n"
            "GET /apps/api/228/mcp?access_token=secret123 HTTP/1.1\n"
            "Authorization: Bearer tok456\n"
            "2026-01-01T00:00:01 WARN mcp-server-hubitat: retry scheduled with token\n"
            "2026-01-01T00:00:02 INFO mcp-server-hubitat: reconnected on attempt 2\n"
            "curl -H 'Authorization: Bearer AAAAAAAAAAAAAAAA1' http://h/x"
        )
        result = _report({
            "issueType": "bug",
            "title": "E2E report-shape probe",
            "expected": long_expected,
            "actual": "addTrigger returned an error",
            "stepsToReproduce": "1. call hub_set_rule with a switch trigger",
            "llmClient": "hubitat-e2e-suite",
            "llmModel": "n/a (automated suite)",
            "verbatimToolCalls": verbatim,
            "clientLogs": secret_logs,
        })
        assert result.get("success") is True, f"hub_report_issue failed: {result}"
        # This suite's ordinary calls declare no clientInfo, so the server can never confirm the
        # host app and always asks the user about llmClient. Everything actually supplied must be
        # accepted, so no OTHER field may come back as missing.
        missing = [entry.get("field") for entry in (result.get("missingContext") or [])]
        assert [f for f in missing if f != "llmClient"] == [], \
            f"a supplied field was reported missing: {result.get('missingContext')!r}"
        assert isinstance(result.get("preflight"), list), f"preflight must be a list: {result!r}"
        assert "submitUrl" in (result.get("instructions") or ""), \
            f"instructions must point the agent at submitUrl: {result.get('instructions')!r}"
        # The link carries the diagnostic prefill: a label marking the issue tool-generated plus
        # the issue-form field ids, so a maintainer sees version/firmware/client without asking.
        submit_url = result.get("submitUrl") or ""
        assert "labels=diag-prefilled" in submit_url, \
            f"submitUrl must carry the diag-prefilled label: {submit_url!r}"
        assert "mcp_version=" in submit_url, \
            f"submitUrl must prefill mcp_version: {submit_url!r}"
        report = result.get("report") or ""
        # Hub model is the hardware model hub_get_info reports, never the internal hardwareID.
        hub_model = re.search(r"^- \*\*Hub model:\*\* (.+)$", report, re.MULTILINE)
        assert hub_model, "report is missing the Hub model line"
        expected_model = self.client.call_tool("hub_get_info", {}).get("model")
        assert hub_model.group(1) == expected_model, \
            f"report Hub model {hub_model.group(1)!r} != hub_get_info model {expected_model!r}"
        for marker in (
            "## Environment",
            "- **Connection:** ",
            "- **Client (MCP self-report):** ",
            "- **Protocol version:** ",
            "- **Model:** ",
            "## MCP Server Settings",
            "## Verbatim Tool Calls",
            "## Client-Side Logs",
            "## Recent Error/Warning Logs",
        ):
            assert marker in report, f"report missing {marker!r}: {report[:800]!r}"
        assert "## Verbatim Tool Calls\n````text\n" in report, \
            f"verbatim fence did not escalate past the pasted ```: {report!r}"
        expected_block = report.split("### Expected\n", 1)[1].split("\n### Actual", 1)[0]
        too_long = [line for line in expected_block.split("\n") if len(line) > 100]
        assert not too_long, f"expected prose was not wrapped at 100 chars: {too_long!r}"
        assert "access_token=<redacted>" in report, (
            f"the pasted access_token was not redacted: {report!r}")
        assert "Authorization: Bearer <redacted>" in report, (
            f"the pasted Authorization header was not redacted: {report!r}")
        assert "secret123" not in report and "tok456" not in report, (
            f"a credential survived into the private-mode report: {report!r}")
        assert "reconnected on attempt 2" in report, (
            f"the log line after one ending in 'token' was eaten by the redaction: {report!r}")
        assert "retry scheduled with token" in report, (
            f"a line merely ending in the word 'token' was redacted: {report!r}")
        assert "curl -H 'Authorization: Bearer <redacted>' http://h/x" in report, (
            f"the redaction ate the closing quote or the URL after the credential: {report!r}")
        assert "AAAAAAAAAAAAAAAA1" not in report, (
            f"a bearer credential survived into the private-mode report: {report!r}")

        # Public mode withholds both pasted sections outright, credentials or not, and
        # includeRawLogs=true cannot opt them back in.
        public = _report({
            "issueType": "bug",
            "title": "E2E report-shape probe (public)",
            "expected": "the pasted sections are withheld",
            "actual": "they were rendered verbatim",
            "privacyMode": "public",
            "includeRawLogs": True,
            "llmClient": "hubitat-e2e-suite",
            "llmModel": "n/a (automated suite)",
            "verbatimToolCalls": verbatim,
            "clientLogs": secret_logs,
        })
        assert public.get("success") is True, f"public-mode hub_report_issue failed: {public}"
        public_report = public.get("report") or ""
        for section in ("## Verbatim Tool Calls", "## Client-Side Logs"):
            parts = public_report.split(section, 1)
            assert len(parts) == 2, f"public report missing {section!r}: {public_report[:800]!r}"
            assert "omitted in public mode" in parts[1].split("\n##", 1)[0], (
                f"{section!r} was not withheld in public mode: {public_report!r}")
        assert "HTTP 500 Internal error" not in public_report, (
            f"the verbatim payload leaked into a public report: {public_report!r}")
        assert "transport closed" not in public_report, (
            f"the client-log payload leaked into a public report: {public_report!r}")
        assert "includeRawLogs=true" not in public_report, (
            f"a public placeholder still offered an override that no longer exists: {public_report!r}")

        # agent_behavior asks for the same evidence as a bug and renders the same sections.
        agent = _report({
            "issueType": "agent_behavior",
            "title": "E2E agent-behavior probe",
            "expected": "the agent picks the documented tool",
            "actual": "the agent guessed a tool name",
        })
        assert agent.get("success") is True, f"agent_behavior report failed: {agent}"
        agent_missing = [entry.get("field") for entry in (agent.get("missingContext") or [])]
        assert "verbatimToolCalls" in agent_missing and "clientLogs" in agent_missing, \
            f"agent_behavior must ask for the same evidence as a bug: {agent_missing!r}"
        agent_preflight = agent.get("preflight") or []
        assert len(agent_preflight) == 1 and "verbatimToolCalls" in agent_preflight[0], \
            f"agent_behavior preflight must be the single verbatim step: {agent_preflight!r}"
        assert "## Verbatim Tool Calls\n_Not provided_" in (agent.get("report") or ""), \
            f"agent_behavior must render the missing-evidence gap: {agent.get('report')!r}"

    @test("system_tools")
    def test_hub_mesh_read(self) -> None:
        # Hub Mesh is Hubitat's hub-to-hub device/variable sharing between hubs on the same LAN --
        # NOT the Z-Wave/Zigbee radio mesh (that is hub_get_radio_details). READ-ONLY coverage: the
        # e2e hub is shared CI infrastructure, so nothing in this file ever enables/disables mesh,
        # retargets mode-following, or stores a peer token (see test_hub_mesh_update_validation).
        res = self.client.call_tool("hub_get_hub_mesh")
        assert isinstance(res, dict), f"hub_get_hub_mesh returned {type(res).__name__}"
        assert isinstance(res.get("success"), bool), \
            f"hub_get_hub_mesh did not return a boolean success: {sorted(res)}"

        if not res["success"]:
            # Firmware that predates Hub Mesh (or an unreachable endpoint) must degrade to the
            # structured runtime-error contract, never a bare failure.
            assert res.get("error"), f"success=false without an error: {sorted(res)}"
            assert res.get("note"), f"success=false without an actionable note: {sorted(res)}"
            print("    [E2E-GAP] this hub did not serve /hub2/hubMeshJson -- only the structured "
                  f"success:false contract was exercised: {res.get('error')}")
            return

        for k in ("hubMeshEnabled", "fullRefreshInterval", "modeHubId", "peers",
                  "privateDeviceCount", "localHubVariableCount", "note"):
            assert k in res, f"hub_get_hub_mesh missing '{k}': {sorted(res)}"
        for k in ("peers", "sharedDevices", "localLinkedDevices", "availableLinkedDevices",
                  "sharedHubVariables", "localLinkedHubVariables", "availableLinkedHubVariables"):
            assert isinstance(res.get(k), list), f"{k} is not a list: {res.get(k)!r}"
        assert isinstance(res["modeHubId"], str), f"modeHubId is not a string: {res['modeHubId']!r}"

        # The unshared-device set and the local hub variables come back as COUNTS only -- the full
        # lists live in hub_list_devices / hub_list_variables and would blow the response budget.
        assert isinstance(res["privateDeviceCount"], int), \
            f"privateDeviceCount is not an int: {res['privateDeviceCount']!r}"
        assert isinstance(res["localHubVariableCount"], int), \
            f"localHubVariableCount is not an int: {res['localHubVariableCount']!r}"
        assert "privateDevices" not in res, "privateDevices must be a count only, not the full list"
        assert "localHubVariables" not in res, "localHubVariables must be a count only, not the full list"

        # The mesh token is a credential: absent entirely unless include_token=true was asked for.
        assert "hubMeshToken" not in res, \
            "hub_get_hub_mesh returned hubMeshToken without include_token=true"

        # include_token=true surfaces the credential KEY. Prove the flag works by presence ONLY --
        # this test never asserts the token's value (the harness's own -v response log may still print
        # the raw response body, so this is not a secrecy guarantee, only that the test does not read it).
        with_token = self.client.call_tool("hub_get_hub_mesh", {"include_token": True})
        assert isinstance(with_token, dict) and with_token.get("success") is True, \
            f"hub_get_hub_mesh(include_token=true) did not succeed: {sorted(with_token) if isinstance(with_token, dict) else type(with_token).__name__}"
        assert "hubMeshToken" in with_token, \
            "hub_get_hub_mesh(include_token=true) did not surface the hubMeshToken key"

    @test("system_tools")
    def test_hub_mesh_update_validation(self) -> None:
        # NO state-changing Hub Mesh write is ever made against the shared CI hub: enable/disable
        # needs a hub reboot, and follow-modes / peer tokens are hub-wide settings other tests would
        # inherit. What IS proven live is the validation contract -- every rejection fires BEFORE
        # any hub call and surfaces as an isError validation result, so a caller can correct and
        # retry safely.
        print("    [E2E-GAP] hub_update_hub_mesh state changes (enable/disable, sync interval, "
              "follow-modes, peer token) are intentionally NOT e2e-tested -- they mutate shared hub "
              "state and enable/disable needs a reboot; ToolHubMeshSpec covers them against a mocked hub.")
        for args, needle, label in (
            ({}, "at least one field", "no settable field"),
            ({"full_refresh_interval": 42}, "full_refresh_interval", "out-of-set interval"),
            ({"full_refresh_interval": 300.5}, "full_refresh_interval", "fractional interval"),
            ({"peer_hub_id": "12"}, "peer_", "peer_hub_id without peer_token"),
            ({"enabled": "true"}, "enabled", "non-boolean enabled"),
        ):
            try:
                detail = self.client.call_tool("hub_update_hub_mesh", args)
            except McpError as exc:  # McpToolError (subclass): the isError validation envelope
                assert needle.lower() in str(exc).lower(), \
                    f"{label}: expected '{needle}' in the rejection, got: {exc}"
                continue
            raise AssertionError(
                f"{label}: hub_update_hub_mesh({args}) must be rejected by validation, got: {detail}")

    @test("system_tools")
    def test_set_system_settings(self) -> None:
        # hub_set_system_settings writes hub-GLOBAL location/identity settings via a read-merge of
        # GET /hub/details/json -> POST /location/update. To keep the sacrificial e2e hub usable
        # mid-suite this test NEVER changes timeZone (a tz change reboots the hub). It proves EVERY
        # aspect of the tool:
        #   1 ALL settable non-tz fields (temperatureScale, hubName, latitude, longitude, zipCode)
        #     round-trip to their CURRENT values in ONE atomic no-op POST -> success + each in applied
        #     (the read-merge preserves everything; nothing actually changes)
        #   2 out-of-range latitude is rejected by validation (-32602) before any hub write
        #   3 the timeZone leg's confirm gate REJECTS without confirm AND the hub's timeZone is
        #     unchanged afterward (no reboot, nothing mutated)
        # Every write goes through _set_call so an "excessive hub load" limiter trip bounces the app via
        # the watchdog and retries once -- the same contract the mode-lifecycle test uses.
        def _set_call(args: dict, label: str) -> Any:
            try:
                return self.client.call_tool("hub_set_system_settings", args)
            except McpToolError as exc:
                if "excessive hub load" in str(exc) and self._clear_load_throttle(f"{label}: {exc}"):
                    return self.client.call_tool("hub_set_system_settings", args)
                raise

        # Read current settings to round-trip them (no-op writes -- nothing actually changes).
        before = self.client.call_tool("hub_get_info")
        assert isinstance(before, dict), f"hub_get_info returned {type(before)}"
        cur_tz = before.get("timeZone")

        # 1 -- every readable settable non-tz field, set back to its CURRENT value in ONE atomic POST.
        # (name/latitude/longitude/zipCode are PII -> present only when the Read master is ON, the
        # default; include each only when readable so the test still works with Read OFF.)
        roundtrip: dict = {}
        if before.get("temperatureScale") in ("F", "C"):
            roundtrip["temperatureScale"] = before["temperatureScale"]
        if before.get("name"):
            roundtrip["hubName"] = before["name"]
        if before.get("latitude") is not None:
            roundtrip["latitude"] = before["latitude"]
        if before.get("longitude") is not None:
            roundtrip["longitude"] = before["longitude"]
        if before.get("zipCode"):
            roundtrip["zipCode"] = before["zipCode"]
        if roundtrip:
            r1 = _set_call(roundtrip, "settings round-trip")
            assert isinstance(r1, dict) and r1.get("success") is True, f"settings round-trip failed: {r1}"
            for k in roundtrip:
                assert k in (r1.get("applied") or []), f"applied did not include {k}: {r1}"

        # 2 -- out-of-range latitude must be rejected by validation (-32602) before any hub write.
        rejected_lat = False
        lat_detail = None
        try:
            lat_detail = self.client.call_tool("hub_set_system_settings", {"latitude": 999})
            blob = (lat_detail if isinstance(lat_detail, str) else json.dumps(lat_detail)).lower()
            rejected_lat = (isinstance(lat_detail, dict) and bool(lat_detail.get("isError"))) \
                or "latitude" in blob or "between" in blob
        except McpError as exc:  # also catches McpToolError (subclass)
            lat_detail = str(exc)
            rejected_lat = "latitude" in lat_detail.lower() or "between" in lat_detail.lower()
        assert rejected_lat, f"out-of-range latitude (999) must be rejected by validation, got: {lat_detail}"
        # dismissAlert without a key is refused before anything reaches /hub/dismissAlert.
        self._expect_tool_refusal("hub_set_system_settings", {"dismissAlert": {"version": "1"}}, "dismissAlert must be {key")

        # 3 -- the timeZone confirm gate: a tz change WITHOUT confirm must be refused (no reboot). The
        # refusal surfaces as a raised McpError/-32602 ("confirm"/"backup"/"safety check"), OR an
        # isError envelope returned as a dict -- accept either. The tz value passed equals the CURRENT
        # tz so that even if the gate were (wrongly) bypassed, nothing would actually change.
        refused = False
        detail = None
        gate_args = {"timeZone": cur_tz or "America/New_York"}
        try:
            detail = self.client.call_tool("hub_set_system_settings", gate_args)
            blob = (detail if isinstance(detail, str) else json.dumps(detail)).lower()
            refused = (isinstance(detail, dict) and bool(detail.get("isError"))) \
                or "confirm" in blob or "backup" in blob or "safety check" in blob
        except McpError as exc:  # also catches McpToolError (subclass)
            detail = str(exc)
            refused = any(s in detail.lower() for s in ("confirm", "backup", "safety check"))
        assert refused, \
            f"hub_set_system_settings timeZone change without confirm must be refused by the gate, got: {detail}"

        # Confirm nothing changed: the hub's timeZone is still what it was before the rejected call.
        after = self.client.call_tool("hub_get_info")
        assert after.get("timeZone") == cur_tz, \
            f"timeZone changed despite the confirm-gate rejection: before={cur_tz!r} after={after.get('timeZone')!r}"

    @test("system_tools")
    def test_set_system_settings_dark_mode(self) -> None:
        # hub_set_system_settings(darkMode) sets the admin-UI theme via an INDEPENDENT setter
        # (GET /hub/applyDarkMode/<bool>, HTTP 200 empty, no read-back -- /hub/details/json has no
        # dark/theme key). FIRMWARE-TOLERANT: /hub/applyDarkMode may not exist on older firmware
        # (it 404s there). The tool then returns a
        # structured {success:false, error:"Failed to apply dark mode: ..."} envelope (NOT isError,
        # so call_tool hands it back as a dict). Treat a genuine endpoint-absent failure as a CLEAN
        # SKIP, distinct from a flaky relay 504 (which the runner retries). Sets dark then reverts to
        # light so the hub theme is left as we found it.
        def _dark_call(on: bool) -> Any:
            args = {"darkMode": on}
            try:
                return self.client.call_tool("hub_set_system_settings", args)
            except McpToolError as exc:
                msg = str(exc)
                if "excessive hub load" in msg and self._clear_load_throttle(f"darkMode={on}: {exc}"):
                    return self.client.call_tool("hub_set_system_settings", args)
                # A darkMode failure can also surface as an isError-raised McpToolError; a
                # firmware-absent endpoint is a clean skip, a relay 504 a retryable failure.
                if "dark mode" in msg.lower():
                    raise SkipTest(
                        f"/hub/applyDarkMode appears absent on this firmware (skip): {msg}"
                    ) from exc
                raise

        # Set dark mode ON.
        on_res = _dark_call(True)
        if isinstance(on_res, dict) and on_res.get("success") is False:
            # The tool ran but the endpoint rejected the apply -- firmware without /hub/applyDarkMode.
            raise SkipTest(
                f"/hub/applyDarkMode not supported on this firmware (skip): {on_res.get('error')}"
            )
        assert isinstance(on_res, dict) and on_res.get("success") is True, \
            f"darkMode=true did not succeed: {on_res}"
        assert "darkMode" in (on_res.get("applied") or []), \
            f"applied did not include darkMode: {on_res}"

        # Revert to light mode so the hub is left as found (best-effort: a revert failure after a
        # successful ON is still a real regression, so assert it too).
        off_res = _dark_call(False)
        assert isinstance(off_res, dict) and off_res.get("success") is True, \
            f"darkMode=false (revert) did not succeed: {off_res}"
        assert "darkMode" in (off_res.get("applied") or []), \
            f"revert applied did not include darkMode: {off_res}"

    @test("system_tools")
    def test_list_libraries(self) -> None:
        result = self.client.call_tool("hub_list_libraries")
        libs = result if isinstance(result, list) else result.get("libraries", [])
        assert isinstance(libs, list), "hub_list_libraries did not return a list"
        source = result.get("source") if isinstance(result, dict) else None
        # The assertions below require the hub's library API to return its populated JSON-array
        # shape (source == "hub_api"). The degraded shapes (hub_api_raw / unavailable) return an
        # empty list, so requiring hub_api here turns a genuinely-unreadable library API into a
        # clear failure. level99's hub returns the array today.
        assert source == "hub_api", (
            f"hub_list_libraries did not return the populated hub API shape (source={source!r})"
        )
        for lib in libs:
            assert "id" in lib and "name" in lib, "library summary missing id/name"
            assert "source" not in lib, "hub_list_libraries should omit source (read it via hub_get_source)"
        # The package ships no libraries since issue #522 (the parent is installed with them
        # inlined): a fresh hub lists none of ours, a hub upgraded from 4.6.0 still carries the old
        # `mcp` ones. Validate the list against the source reader on whichever library the hub has.
        if not libs:
            print("    [INFO] hub has no Libraries Code entries; list shape validated, source cross-check skipped")
            return
        lib = libs[0]
        readback = self.client.call_tool("hub_get_source", {
            "type": "library", "id": str(lib["id"]), "length": 4000,
        })
        assert readback.get("success") is True, f"installed library source read failed: {readback}"
        assert readback.get("source"), f"library {lib['id']} read back empty"
        assert readback.get("version") is not None and readback.get("version") == lib.get("version"), \
            f"library source/list versions differ: source={readback.get('version')}, list={lib.get('version')}"

    def _hub_fw_at_least(self, version: str) -> bool:
        """Whether the hub's firmware is at least `version` (dotted numbers), from one cached hub_get_info."""
        fw = getattr(self, "_hub_fw_cached", None)
        if fw is None:
            fw = str(self.client.call_tool("hub_get_info", {}).get("firmwareVersion") or "")
            self._hub_fw_cached = fw
        def parts(v: str) -> list:
            return [int(p) if p.isdigit() else 0 for p in v.split(".")]
        have, want = parts(fw), parts(version)
        width = max(len(have), len(want))
        return bool(fw) and have + [0] * (width - len(have)) >= want + [0] * (width - len(want))

    def _get_hub_info_optin(self) -> dict:
        """hub_get_info with BOTH additive opt-in blocks in ONE call, shared by the two opt-in tests
        (they read DISJOINT keys: healthAlerts vs platformUpdate/appUpdate). Lazy + cached; the result is
        an immutable read, so a fresh fetch falls back when the stash is unset (isolation-safe). Does NOT
        affect test_get_hub_info, which makes its own no-flags call and asserts healthAlerts ABSENT."""
        cached = self._hub_info_optin
        if cached is None:
            cached = self.client.call_tool(
                "hub_get_info", {"includeHealthAlerts": True, "includeAppUpdate": True, "includeSubscriptions": True})
            self._hub_info_optin = cached
        return cached

    @test("system_tools")
    def test_hub_get_info_health_alerts_opt_in(self) -> None:
        # #13: the full alerts block appears only with includeHealthAlerts=true.
        info = self._get_hub_info_optin()
        ha = info.get("healthAlerts")
        assert ha is not None, f"includeHealthAlerts=true but healthAlerts absent/null: {sorted(info)}"
        for k in ("safeMode", "active", "details"):
            assert k in ha, f"healthAlerts missing '{k}': {redact_hub_payload(ha, 'healthAlerts')}"
        assert isinstance(ha["active"], list), f"healthAlerts.active not a list: {ha['active']}"
        assert isinstance(ha["details"], dict), f"healthAlerts.details not a dict: {redact_hub_payload(ha['details'], 'healthAlerts')}"
        # platform-update fields are surfaced via platformUpdate, not duplicated in the alert details
        assert "platformUpdateAvailable" not in ha["details"], \
            f"platformUpdate leaked into healthAlerts.details: {sorted(ha['details'])}"
        # Firmware 2.5.2.129+ reports alerts only as alertItems: every item must surface in active.
        items = ha["details"].get("alertItems")
        if isinstance(items, list):
            keys = sorted({str(i["key"]) for i in items if isinstance(i, dict) and i.get("key")})
            assert ha["active"] == keys, f"healthAlerts.active must list the alert item keys {keys}: {redact_hub_payload(ha, 'healthAlerts')}"
            # 2.5.2.129: each item is also served as a dismissal handle for hub_set_system_settings.
            assert [i.get("key") for i in ha.get("items") or []] == [i.get("key") for i in items if isinstance(i, dict) and i.get("key")], \
                f"healthAlerts.items must mirror the alert items: {redact_hub_payload(ha.get('items'), 'healthAlerts')}"
            assert all(isinstance(i.get("dismissible"), bool) for i in ha.get("items") or []), \
                f"alert items must carry a dismissible flag: {redact_hub_payload(ha.get('items'), 'healthAlerts')}"
        # includeSubscriptions (same opt-in call): the four subscriptions, or an explicit error on old firmware.
        subs = info.get("subscriptions") or {}
        assert "error" in subs or "hubProtect" in subs, f"subscriptions block has neither data nor an error: {subs}"
        if self._hub_fw_at_least("2.5.2"):
            assert "hubProtect" in subs, f"subscriptions unreadable on 2.5.2+: {subs}"
        if "hubProtect" in subs:
            assert all(isinstance(subs[k].get("active"), bool) for k in ("hubProtect", "remoteAdmin", "cloudBackup", "fullLocalBackup") if k in subs), \
                f"subscription entries must carry active: {subs}"

    @test("system_tools")
    def test_hub_get_info_update_reads(self) -> None:
        # Folded (was hub_get_update_status): hub_get_info carries platformUpdate (the pending HUB
        # firmware) always, and the MCP-app version check under appUpdate when includeAppUpdate=true.
        # Shares the one both-flags call with test_hub_get_info_health_alerts_opt_in (disjoint keys).
        res = self._get_hub_info_optin()
        assert "platformUpdate" in res, f"missing platformUpdate: {sorted(res)}"
        assert "available" in res["platformUpdate"], f"platformUpdate shape wrong: {res['platformUpdate']}"
        pu = res["platformUpdate"]
        # 2.5.2.129 dropped the update flag; the alert item or the platform's latest-version check
        # answers instead, so null is left only with a note pointing at Check for Updates.
        if pu.get("available") is True:
            assert "availableVersion" in pu, f"a pending update must carry availableVersion: {pu}"
        elif pu.get("available") is None:
            assert "Check for Updates" in str(pu.get("note")), f"an unknown pending-update state needs its note: {pu}"
        assert "appUpdate" in res, f"includeAppUpdate did not attach appUpdate: {sorted(res)}"
        au = res["appUpdate"]
        assert "installedVersion" in au, f"appUpdate shape wrong: {au}"
        # The live test hub reaches GitHub, so an app-check error is a real failure, not a soft skip.
        assert "error" not in au, f"appUpdate returned an error: {au}"
        # The metadata fields are always present on the non-error path: checkInProgress is a bool
        # (a fresh async check was kicked off, or it failed to start) and lastChecked is a string
        # (a formatted timestamp, or "never").
        assert isinstance(au.get("checkInProgress"), bool), f"checkInProgress not a bool: {au}"
        assert isinstance(au.get("lastChecked"), str), f"lastChecked not a string: {au}"
        # The follow-up the description asks for settles: once a check has completed, calls in the
        # next five minutes report it without starting another, so checkInProgress turns false.
        settled = au
        for _ in range(8):
            if settled.get("checkInProgress") is False:
                break
            time.sleep(3)
            settled = self.client.call_tool("hub_get_info", {"includeAppUpdate": True}).get("appUpdate") or {}
        assert settled.get("checkInProgress") is False, f"checkInProgress never settled to false: {settled}"
        # updateAvailable is derived from the versions shown, so it can never contradict them: if an
        # update is flagged available, latestVersion must actually differ from installedVersion (the
        # bug being guarded was a stale updateAvailable:true reading as available when latest==installed).
        if au.get("latestVersion") not in (None, "unknown (check in progress)"):
            if au.get("updateAvailable") is True:
                assert au["latestVersion"] != au["installedVersion"], (
                    f"updateAvailable true but latest == installed: {au}"
                )
            elif au["latestVersion"] == au["installedVersion"]:
                assert au.get("updateAvailable") is False, (
                    f"latest == installed but updateAvailable not False: {au}"
                )

